<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{Message,Modal}from'@arco-design/web-vue';import{adminApi,type AdminFileRow}from'@/api/admin';import{PublicApiError}from'@/api/client';import{formatBytes,formatDate,optionalPositiveInt}from'@/utils/format'
const rows=ref<AdminFileRow[]>([]),loading=ref(false),hasMore=ref(false),next=ref(0);const filters=reactive({search:'',userId:''});function report(e:unknown){Message.error(e instanceof PublicApiError?e.message:'请求失败')};async function load(append=false){loading.value=true;try{const page=await adminApi.files({beforeId:append?next.value:undefined,limit:50,search:filters.search,userId:optionalPositiveInt(filters.userId)});rows.value=append?[...rows.value,...page.list]:page.list;hasMore.value=page.hasMore;next.value=page.nextBeforeId}catch(e){report(e)}finally{loading.value=false}}
async function download(row:AdminFileRow){try{await adminApi.downloadFile(row)}catch(e){report(e)}};function remove(row:AdminFileRow){Modal.warning({title:'删除文件引用',content:`确认删除 ${row.fileName} 的用户文件引用？共享物理对象将保留。`,hideCancel:false,onOk:async()=>{try{await adminApi.deleteFile(row.id);Message.success('文件引用已删除');await load()}catch(e){report(e)}}})};onMounted(()=>load())
</script>
<template><section class="page-stack"><a-card :bordered="false"><div class="toolbar"><div><h2>文件管理</h2><p>查看用户文件引用与安全元数据；下载经管理员专用受保护接口。</p></div><a-space><a-input v-model="filters.search" placeholder="文件名"/><a-input v-model="filters.userId" placeholder="用户 ID"/><a-button type="primary" @click="load()">查询</a-button></a-space></div></a-card><a-card :bordered="false"><a-table row-key="id" :data="rows" :loading="loading" :pagination="false"><template #columns><a-table-column title="文件"><template #cell="{record}"><strong>{{record.fileName}}</strong><div class="muted">#{{record.id}} · {{record.mimeType}}</div></template></a-table-column><a-table-column title="所有者"><template #cell="{record}">{{record.userNickname}} (#{{record.userId}})</template></a-table-column><a-table-column title="大小" :width="110"><template #cell="{record}">{{formatBytes(record.size)}}</template></a-table-column><a-table-column title="SHA-256" :width="190"><template #cell="{record}"><span class="mono">{{record.sha256.slice(0,16)}}…</span></template></a-table-column><a-table-column title="上传时间" :width="180"><template #cell="{record}">{{formatDate(record.createdAt)}}</template></a-table-column><a-table-column title="操作" :width="170"><template #cell="{record}"><a-space><a-button size="small" @click="download(record)">下载</a-button><a-button size="small" status="danger" @click="remove(record)">删除</a-button></a-space></template></a-table-column></template></a-table><div class="load-more"><a-button v-if="hasMore" @click="load(true)">加载更多</a-button></div></a-card></section></template>
